#!/usr/bin/env python3
"""Regenerate the auto-generated section of results_a0007_postfw.md from whatever
a0007 output files exist, and draw the attribution conclusions mechanically.

Run by a0007-report.sh as a SLURM dependency job so it executes after the debug
jobs finish, with no interactive session required.

Only the block between AUTO-BEGIN / AUTO-END markers is touched; everything
hand-written in the summary file is left alone. If the markers are absent the
block is appended once.
"""
import glob
import os
import re
import subprocess
import sys
from datetime import datetime

HERE = os.path.dirname(os.path.abspath(__file__))
SUMMARY = os.path.join(HERE, "results_a0007_postfw.md")
OUTDIR = os.path.join(HERE, "out-1node-a0007")
BEGIN = "<!-- AUTO-BEGIN: regenerated by a0007_autoreport.py -->"
END = "<!-- AUTO-END -->"

sys.path.insert(0, HERE)
from extract_a0007 import parse  # noqa: E402

HEALTHY = 10.0   # GB/s; below this a collective is considered collapsed
COLLAPSED = 5.0



SCATDBG_RE = re.compile(r"SCATDBG=(\S+) prog=(\S+).*?extra_env=(.*?)\s*%%")
SCATDBG_SIZE = 268435456   # 256 MiB - the top of the debug job's range


def parse_scatdbg(path):
    """extract_a0007.parse cannot read the debug job: its section labels carry
    prog=/devices=/extra_env= after the collective name, and it never reaches
    16 GB. Parse that format separately."""
    out, cur = {}, None
    for ln in open(path, errors="replace"):
        m = SCATDBG_RE.search(ln)
        if m:
            cur = (m.group(1), m.group(2), m.group(3).strip())
            out.setdefault(cur, None)
            continue
        if cur is None:
            continue
        f = ln.split()
        if len(f) >= 12 and f[0].isdigit() and int(f[0]) == SCATDBG_SIZE:
            try:
                out[cur] = max(float(f[-6]), float(f[-2]))
            except ValueError:
                pass
    return out


def load_scatdbg():
    res = {}
    for path in glob.glob(os.path.join(OUTDIR, "*scatdbg*")):
        res.update(parse_scatdbg(path))
    return res


def collect():
    """{(file, case, collective): busbw} for every a0007 output present."""
    out = {}
    for path in sorted(glob.glob(os.path.join(OUTDIR, "a0007-*"))):
        if os.path.isdir(path) or os.path.getsize(path) < 500:
            continue
        base = os.path.basename(path)
        try:
            for r in parse(path):
                out[(base, r["case"], r["prog"])] = r
        except Exception as exc:                      # never let one bad file stop the report
            print("WARN: could not parse %s: %s" % (base, exc), file=sys.stderr)
    return out


def find(recs, filepat, casepat, prog):
    """First busbw matching a file substring and a case regex."""
    for (f, case, p), r in sorted(recs.items()):
        if p != prog:
            continue
        if filepat not in f:
            continue
        if not re.search(casepat, case):
            continue
        if r["busbw"] is not None:
            return r["busbw"]
    return None


def fmt(v):
    return "—" if v is None else "%.2f" % v


def repeatability(sd):
    """PART A of the scatter debug: 3 repeats of the same case."""
    rows = []
    for prog in ("scatter", "alltoall", "gather"):
        vals = [sd.get(("rep%d-%s" % (r, prog), prog, "")) for r in (1, 2, 3)]
        vals = [v for v in vals if v]
        if vals:
            spread = (max(vals) - min(vals)) / max(vals) * 100 if max(vals) else 0
            rows.append((prog, vals, spread))
    return rows


def main():
    recs = collect()
    L = []
    A = L.append
    A(BEGIN)
    A("")
    A("## Auto-generated results (updated %s)" % datetime.now().strftime("%Y-%m-%d %H:%M"))
    A("")
    A("Regenerated by `a0007_autoreport.py`, run as a SLURM dependency job. Hand-written")
    A("sections above are not modified by it.")
    A("")

    # ---- the decisive control: is NCCL_P2P_LEVEL=SYS itself breaking scatter? ----
    A("### Is `NCCL_P2P_LEVEL=SYS` responsible for the scatter/alltoall collapse?")
    A("")
    A("Both columns are a0007, 4 GPUs on socket 0, converged 16 GB. Only the setting differs.")
    A("")
    A("| Collective | NCCL defaults (job 335844) | `NCCL_P2P_LEVEL=SYS` (job 335386) |")
    A("|---|---:|---:|")
    verdict_rows = {}
    for prog in ("sendrecv_perf", "gather_perf", "scatter_perf", "alltoall_perf",
                 "all_reduce_perf"):
        d = find(recs, "a0007-defaults", r"4gpu-socket0", prog)
        y = find(recs, "a0007-socket-", r"4gpu-socket0", prog)
        verdict_rows[prog] = (d, y)
        A("| %s | %s | %s |" % (prog.replace("_perf", ""), fmt(d), fmt(y)))
    A("")

    ds, ys = verdict_rows.get("scatter_perf", (None, None))
    if ds is None:
        A("**Verdict: pending** — the defaults control (job 335844) has not produced a")
        A("`scatter` number yet, so the cause remains unattributed.")
    elif ds >= HEALTHY and ys is not None and ys < COLLAPSED:
        A("**Verdict: `NCCL_P2P_LEVEL=SYS` CAUSES the collapse.** `scatter` is healthy at")
        A("%.2f GB/s with NCCL defaults and falls to %.2f with the workaround. The" % (ds, ys))
        A("workaround therefore has a real cost, and is not a free win: it rescues")
        A("`sendrecv`/ring collectives by ~885x while destroying `scatter` and `alltoall`.")
        A("Users whose workload is scatter- or alltoall-heavy (MoE, tensor-parallel")
        A("all-to-all) should benchmark both settings rather than adopting `SYS` blindly.")
        A("This is NOT a firmware defect and must not be reported as one.")
    elif ds < COLLAPSED and ys is not None and ys < COLLAPSED:
        A("**Verdict: the setting is INNOCENT.** `scatter` is %.2f GB/s at defaults and" % ds)
        A("%.2f with the workaround — collapsed either way. The fault lies with the" % ys)
        A("platform (firmware, driver 595.71.05, or node), not with `NCCL_P2P_LEVEL=SYS`.")
        A("Note the driver changed as well as the PCIe firmware, so this still does not")
        A("isolate the firmware; a non-updated a-node is required for that.")
    else:
        A("**Verdict: inconclusive** — defaults %s vs workaround %s do not fall cleanly"
          % (fmt(ds), fmt(ys)))
        A("either side of the healthy/collapsed thresholds. Needs a human look.")
    A("")

    # ---- repeatability ----
    sd = load_scatdbg()
    reps = repeatability(sd)
    if reps:
        A("### Repeatability (3 consecutive runs, 4 GPU socket 0, busbw @256 MiB)")
        A("")
        A("| Collective | run 1 | run 2 | run 3 | spread |")
        A("|---|---:|---:|---:|---:|")
        for name, vals, spread in reps:
            cells = [fmt(v) for v in vals] + ["—"] * (3 - len(vals))
            A("| %s | %s | %s | %s | %.1f%% |" % (name, cells[0], cells[1], cells[2], spread))
        A("")
        worst = max(s for _, _, s in reps)
        if worst < 10:
            A("All within %.1f%% — the scatter/alltoall figures are **reproducible**, not a" % worst)
            A("transient or a one-off measurement artifact.")
        else:
            A("Spread reaches %.1f%%, so at least one collective is **not stable** across" % worst)
            A("runs. Treat single measurements of it with caution.")
        A("")

    # ---- GPU-count threshold ----
    A("### GPU-count threshold from the debug job (socket 0, busbw @256 MiB)")
    A("")
    A("| Collective | 2 GPU | 3 GPU | 4 GPU |")
    A("|---|---:|---:|---:|")
    for prog in ("scatter", "alltoall", "gather"):
        cells = [fmt(sd.get(("n%d-%s" % (n, prog), prog, ""))) for n in (2, 3, 4)]
        A("| %s | %s | %s | %s |" % (prog, cells[0], cells[1], cells[2]))
    A("")

    # ---- knob sweep ----
    knobs = sorted((lbl, prog, env, v) for (lbl, prog, env), v in sd.items()
                   if lbl.startswith("knob-") and v)
    if knobs:
        A("### Knob sweep on `scatter` / `alltoall` (4 GPU socket 0, busbw @256 MiB)")
        A("")
        A("| setting | collective | busbw (GB/s) |")
        A("|---|---|---:|")
        best = None
        for lbl, prog, env, v in knobs:
            A("| `%s` | %s | %s |" % (env or "(SYS only)", prog, fmt(v)))
            if best is None or v > best[3]:
                best = (lbl, prog, env, v)
        A("")
        if best and best[3] >= HEALTHY:
            A("**`%s` restores %s to %.2f GB/s.**" % (best[2], best[1], best[3]))
        elif best:
            A("Best is `%s` at %.2f GB/s — nothing recovers it." % (best[2], best[3]))
        A("")

    # ---- 1..8 GPU count series ----
    A("### GPU-count series 1–8, `NCCL_P2P_LEVEL=SYS` (converged 16 GB)")
    A("")
    progs = ["sendrecv_perf", "reduce_perf", "broadcast_perf", "gather_perf", "scatter_perf",
             "reduce_scatter_perf", "all_gather_perf", "all_reduce_perf", "alltoall_perf"]
    # where each count lives: (file substring, case regex)
    src = {1: ("a0007-counts", r"^1gpu$"), 2: ("a0007-socket-", r"2gpu-socket0"),
           3: ("a0007-counts", r"^3gpu$"), 4: ("a0007-socket-", r"4gpu-socket0"),
           5: ("a0007-counts", r"^5gpu$"), 6: ("a0007-counts", r"^6gpu$"),
           7: ("a0007-counts", r"^7gpu$"), 8: ("a0007-8gpu", r"^all$")}
    A("| Collective | " + " | ".join("%d GPU" % n for n in range(1, 9)) + " |")
    A("|---|" + "---:|" * 8)
    for prog in progs:
        cells = []
        for n in range(1, 9):
            fp, cp = src[n]
            cells.append(fmt(find(recs, fp, cp, prog)))
        A("| %s | %s |" % (prog.replace("_perf", ""), " | ".join(cells)))
    A("")
    missing = [n for n in range(1, 9) if find(recs, src[n][0], src[n][1], "sendrecv_perf") is None]
    if missing:
        A("Counts still missing: %s (job `a0007-counts` supplies 1, 3, 5, 6, 7)."
          % ", ".join(str(m) for m in missing))
        A("")

    # ---- full dump ----
    A("### All extracted measurements")
    A("")
    A("| file | case | collective | algbw | busbw | status |")
    A("|---|---|---|---:|---:|---|")
    for (f, case, prog), r in sorted(recs.items()):
        if r["busbw"] is None and r["status"] == "no data":
            continue
        A("| `%s` | %s | %s | %s | %s | %s |" % (
            f, case, prog.replace("_perf", ""), fmt(r["algbw"]), fmt(r["busbw"]), r["status"]))
    A("")
    A(END)

    block = "\n".join(L) + "\n"
    text = open(SUMMARY).read() if os.path.exists(SUMMARY) else ""
    if BEGIN in text and END in text:
        text = text[:text.index(BEGIN)] + block + text[text.index(END) + len(END) + 1:]
    else:
        text = text.rstrip() + "\n\n---\n\n" + block
    open(SUMMARY, "w").write(text)
    print("a0007_autoreport: wrote %d measurements into %s" % (len(recs), SUMMARY))


if __name__ == "__main__":
    main()
